/// Output format for sizes.
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum OutputFormat {
    Si,
    B,
    K,
    M,
    G,
    T,
    Kb,
    Mb,
    Gb,
    Tb,
}

impl OutputFormat {
    pub fn from_str(s: &str) -> Option<OutputFormat> {
        match s.to_lowercase().as_str() {
            "si" => Some(OutputFormat::Si),
            "b" => Some(OutputFormat::B),
            "k" => Some(OutputFormat::K),
            "m" => Some(OutputFormat::M),
            "g" => Some(OutputFormat::G),
            "t" => Some(OutputFormat::T),
            "kb" => Some(OutputFormat::Kb),
            "mb" => Some(OutputFormat::Mb),
            "gb" => Some(OutputFormat::Gb),
            "tb" => Some(OutputFormat::Tb),
            _ => None,
        }
    }

    pub fn names() -> [&'static str; 10] {
        [
            "si", "b", "k", "m", "g", "t", "kb", "mb", "gb", "tb",
        ]
    }
}

/// Formats a size according to the output format.
pub fn format_data(value: u64, of: OutputFormat) -> String {
    match of {
        OutputFormat::Si => {
            let value = value as f64;
            if value < 1000f64 {
                format!("{}B", value as u64)
            } else {
                let (div, suffix) = si_unit(value);
                let v = value / div;
                if v < 10f64 {
                    format!("{:.1}{}", v, suffix)
                } else {
                    format!("{:.0}{}", v, suffix)
                }
            }
        }
        OutputFormat::B => format!("{}B", value),
        OutputFormat::K => format!("{}K", value / 1024),
        OutputFormat::M => format!("{}M", value / (1024 * 1024)),
        OutputFormat::G => format!("{}G", value / (1024 * 1024 * 1024)),
        OutputFormat::T => format!("{}T", value / (1024u64.pow(4))),
        OutputFormat::Kb => format!("{}K", value / 1000),
        OutputFormat::Mb => format!("{}M", value / 1000000),
        OutputFormat::Gb => format!("{}G", value / 1000000000),
        OutputFormat::Tb => format!("{}T", value / 1000000000000),
    }
}

fn si_unit(value: f64) -> (f64, &'static str) {
    const K: f64 = 1000.0;
    if value < K * K {
        (K, "K")
    } else if value < K * K * K {
        (K * K, "M")
    } else if value < K * K * K * K {
        (K * K * K, "G")
    } else if value < K * K * K * K * K {
        (K * K * K * K, "T")
    } else if value < K * K * K * K * K * K {
        (K * K * K * K * K, "P")
    } else {
        (K * K * K * K * K * K, "E")
    }
}

/// Formats a unix timestamp (seconds) as an ISO-like string in UTC:
/// YYYY-MM-DDTHH:MM:SS
pub fn format_timestamp(secs: i64) -> String {
    // civil-from-days algorithm (Howard Hinnant)
    let days = secs.div_euclid(86400);
    let secs_of_day = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let hour = secs_of_day / 3600;
    let min = (secs_of_day % 3600) / 60;
    let sec = secs_of_day % 60;
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}",
        y, m, d, hour, min, sec
    )
}

/// days since 1970-01-01 -> (year, month, day)
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}
RSEOF
echo written"}

