use std::collections::HashSet;
use std::ffi::OsStr;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

/// Kind of a filesystem entry (used for colouring).
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Folder,
    File,
    SymLink,
    Fifo,
    Socket,
    CharDev,
    BlockDev,
}

/// A node in the walked directory tree.
pub struct Node {
    /// Display name (last component of the path, lossily converted).
    pub name: String,
    /// Full path of this node.
    pub path: PathBuf,
    /// Size (bytes, file count or timestamp depending on the mode).
    pub size: u64,
    pub children: Vec<Node>,
    pub kind: Kind,
    /// true for the root of the tree (given paths or the artificial total)
    pub is_root: bool,
    /// true for the artificial "(total)" node
    pub is_total: bool,
}

impl Node {
    pub fn new(name: String, path: PathBuf, size: u64, kind: Kind) -> Node {
        Node {
            name,
            path,
            size,
            children: Vec::new(),
            kind,
            is_root: false,
            is_total: false,
        }
    }

    pub fn is_folder(&self) -> bool {
        self.kind == Kind::Folder
    }
}

/// Errors collected during the walk, grouped by kind.
pub struct WalkErrors {
    pub not_found: HashSet<String>,
    pub permissions: HashSet<String>,
}

impl WalkErrors {
    pub fn new() -> WalkErrors {
        WalkErrors {
            not_found: HashSet::new(),
            permissions: HashSet::new(),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.not_found.is_empty() && self.permissions.is_empty()
    }

    pub fn add(&mut self, path: &Path, e: &std::io::Error) {
        let p = path.to_string_lossy().to_string();
        if e.kind() == std::io::ErrorKind::PermissionDenied {
            self.permissions.insert(p);
        } else {
            self.not_found.insert(p);
        }
    }

    pub fn add_paths(&mut self, paths: &[PathBuf]) {
        for p in paths {
            let s = p.to_string_lossy().to_string();
            self.not_found.insert(s);
        }
    }
}

/// Filters used while walking.
pub struct Filters {
    /// names to ignore entirely (-X)
    pub ignore_names: Vec<String>,
    /// regexes to exclude (-v and -I)
    pub ignore_regexes: Vec<regex::Regex>,
    /// regexes to include (-e)
    pub include_regexes: Vec<regex::Regex>,
    /// ignore hidden files (-i)
    pub ignore_hidden: bool,
    /// minimum file size (-z), None = no filter
    pub min_size: Option<u64>,
    /// time filters (mtime/atime/ctime)
    pub time_filters: Vec<(TimeField, i64, TimeSign)>,
    /// device of the root filesystem (-x)
    pub limit_fs: bool,
    pub root_dev: u64,
    /// dereference symlinks (-L)
    pub dereference_links: bool,
}

#[derive(Clone, Copy, PartialEq)]
pub enum TimeField {
    Mtime,
    Atime,
    Ctime,
}

#[derive(Clone, Copy, PartialEq)]
pub enum TimeSign {
    Plus,
    Exact,
    Minus,
}

/// The measurement mode.
pub enum Measure {
    Blocks,
    Apparent,
    FileCount,
    FileTime(TimeField),
}

fn file_size(md: &std::fs::Metadata, measure: &Measure) -> u64 {
    match measure {
        Measure::Apparent => md.len(),
        _ => md.blocks() * 512,
    }
}

fn file_time(md: &std::fs::Metadata, field: TimeField) -> u64 {
    let t = match field {
        TimeField::Mtime => md.modified(),
        TimeField::Atime => md.accessed(),
        TimeField::Ctime => md.ctime(),
    };
    match t {
        Ok(t) => t
            .duration_since(UNIX_EPOCH)
