fn kind_of(md: &std::fs::Metadata) -> Kind {
    let ft = md.file_type();
    if ft.is_dir() {
        Kind::Folder
    } else if ft.is_symlink() {
        Kind::SymLink
    } else if ft.is_fifo() {
        Kind::Fifo
    } else if ft.is_socket() {
        Kind::Socket
    } else if ft.is_char_device() {
        Kind::CharDev
    } else if ft.is_block_device() {
        Kind::BlockDev
    } else {
        Kind::File
    }
}

/// Determine the colour-relevant kind, resolving symlinks.
fn resolve_kind(path: &Path, md: &std::fs::Metadata) -> Kind {
    let k = kind_of(md);
    if k == Kind::SymLink {
        if let Ok(target) = std::fs::metadata(path) {
            return kind_of(&target);
        }
        return Kind::File;
    }
    k
}

/// Walks a directory tree and returns the root node.
pub fn walk(path: &Path, filters: &Filters, measure: &Measure, errors: &mut WalkErrors) -> Node {
    match walk_inner(path, filters, measure, errors, 0) {
        Some(n) => n,
        None => Node::new(String::new(), path.to_path_buf(), 0, Kind::File),
    }
}

fn walk_inner(
    path: &Path,
    filters: &Filters,
    measure: &Measure,
    errors: &mut WalkErrors,
    depth: usize,
) -> Option<Node> {
    // metadata: follow symlinks when asked to
    let md = if filters.dereference_links {
        std::fs::metadata(path)
    } else {
        std::fs::symlink_metadata(path)
    };
    let md = match md {
        Ok(m) => m,
        Err(e) => {
            errors.add(path, &e);
            return None;
        }
    };
    let kind = resolve_kind(path, &md);
    let own_size = file_size(&md, measure);
    let own_time = file_time(&md, TimeField::Mtime);

    // try to read the directory
    let entries = match std::fs::read_dir(path) {
        Ok(e) => e,
        Err(e) => {
            if md.is_file() && !filters.dereference_links {
                // a plain file
                let name = display_name(path);
                let mut node = Node::new(name, path.to_path_buf(), own_size, Kind::File);
                if measure_is_time(measure) {
                    node.size = file_time(&md, time_field(measure));
                }
                if measure_is_count(measure) {
                    node.size = 1;
                }
                if include_node(path, filters) && !excluded_time(&md, filters) {
                    return Some(node);
                }
                return None;
            }
            errors.add(path, &e);
            return None;
        }
    };

    let mut node = Node::new(display_name(path), path.to_path_buf(), own_size, kind);
    let mut total = own_size;
    let mut count = 0u64;
    let mut max_time = own_time;
    let mut any_child = false;

    let mut entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
    // sort by name to make the tie-breaks stable w.r.t. read order
    entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));

    for entry in entries {
        let child_path = entry.path();
        let child_name = entry.file_name().to_string_lossy().to_string();
        if filters.ignore_hidden && child_name.starts_with('.') {
            continue;
        }
        if filters.ignore_names.iter().any(|n| *n == child_name) {
            continue;
        }
        let child_md = if filters.dereference_links {
            match std::fs::metadata(&child_path) {
                Ok(m) => m,
                Err(e) => {
                    errors.add(&child_path, &e);
                    continue;
                }
            }
        } else {
            match std::fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(e) => {
                    errors.add(&child_path, &e);
                    continue;
                }
            }
        };
        if filters.limit_fs {
            use std::os::unix::fs::MetadataExt;
            if child_md.dev() != filters.root_dev {
                continue;
            }
        }
        if !filters.ignore_regexes.is_empty()
            && filters
                .ignore_regexes
                .iter()
                .any(|r| r.is_match(child_path.to_string_lossy().as_ref()))
        {
            continue;
        }
        if !include_node(&child_path, filters) {
            continue;
        }
        if excluded_time(&child_md, filters) {
            continue;
        }
        if let Measure::Apparent | Measure::Blocks = measure {
            if let Some(min) = filters.min_size {
                let sz = file_size(&child_md, measure);
                if sz <= min {
                    continue;
                }
            }
        }
        let is_dir = child_md.is_dir() || (filters.dereference_links && child_md.file_type().is_symlink());
        let child = if is_dir {
            if depth > 200 {
                continue;
            }
            match walk_inner(&child_path, filters, measure, errors, depth + 1) {
                Some(c) => c,
                None => continue,
            }
        } else {
            let k = resolve_kind(&child_path, &child_md);
            let mut sz = file_size(&child_md, measure);
            if measure_is_count(measure) {
                sz = 1;
            }
            if measure_is_time(measure) {
                sz = file_time(&child_md, time_field(measure));
            }
            Node::new(child_name, child_path, sz, k)
        };
        count += child.size;
        if measure_is_time(measure) {
            let t = child.size;
            if t > max_time {
                max_time = t;
            }
        } else {
            total += child.size;
        }
        any_child = true;
        node.children.push(child);
    }
    let _ = any_child;
    if measure_is_count(measure) {
        node.size = count;
    } else if measure_is_time(measure) {
        node.size = max_time;
    } else {
        node.size = total;
    }
    Some(node)
}

fn measure_is_count(m: &Measure) -> bool {
    matches!(m, Measure::FileCount)
}

fn measure_is_time(m: &Measure) -> bool {
    matches!(m, Measure::FileTime(_))
}

fn time_field(m: &Measure) -> TimeField {
    match m {
        Measure::FileTime(f) => *f,
        _ => TimeField::Mtime,
    }
}

/// Apply the -e include filters. A directory matching is kept, otherwise only
/// files (or directories with matching children) are kept.
fn include_node(path: &Path, filters: &Filters) -> bool {
    if filters.include_regexes.is_empty() {
        return true;
    }
    let p = path.to_string_lossy();
    filters.include_regexes.iter().any(|r| r.is_match(p.as_ref()))
}

fn excluded_time(md: &std::fs::Metadata, filters: &Filters) -> bool {
    if filters.time_filters.is_empty() || md.is_dir() {
        return false;
    }
    use std::os::unix::fs::MetadataExt;
    for (field, n, sign) in &filters.time_filters {
        let secs = match field {
            TimeField::Mtime => md.mtime(),
            TimeField::Atime => md.atime(),
            TimeField::Ctime => md.ctime(),
        };
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let file_days = day_of(secs);
        let now_days = day_of(now);
        let diff = now_days - file_days;
        let target = n + 1;
        let ok = match sign {
            TimeSign::Plus => diff > target,
            TimeSign::Exact => diff == target,
            TimeSign::Minus => diff < target,
        };
        if !ok {
            return true;
        }
    }
    false
}

/// days since epoch for a unix timestamp
fn day_of(secs: i64) -> i64 {
    secs.div_euclid(86400)
}

fn display_name(path: &Path) -> String {
    match path.file_name() {
        Some(n) => n.to_string_lossy().to_string(),
        None => path.to_string_lossy().to_string(),
    }
}

/// Returns the file name component of a path as an OsStr.
pub fn os_name(path: &Path) -> &OsStr {
    path.file_name().unwrap_or(path.as_os_str())
}
