/// Colour-relevant kind, resolving symlinks to their target type.
fn resolve_kind(path: &Path, md: &std::fs::Metadata) -> Kind {
    let k = kind_of(md);
    if k == Kind::SymLink {
        if let Ok(target) = std::fs::metadata(path) {
            return kind_of(&target);
        }
        return Kind::File;
    }
    k
