fn is_executable(md: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::PermissionsExt;
    md.permissions().mode() & 0o111 != 0
}

/// Metadata + kind for a child entry.
struct EntryInfo {
    md: std::fs::Metadata,
}

/// Walks a directory tree, returning the root node.
pub fn walk(
    path: &Path,
    filters: &Filters,
    measure: &Measure,
    errors: &mut WalkErrors,
) -> Option<Node> {
    // metadata for the root
    let md = if filters.dereference_links {
        std::fs::metadata(path)
    } else {
        std::fs::symlink_metadata(path)
    };
    let md = match md {
        Ok(m) => m,
        Err(e) => {
            errors.add(path, &e);
            return None;
        }
    };
    // does it look like a directory we can list?
    match std::fs::read_dir(path) {
        Ok(entries) => {
            let kind = resolve_kind(path, &md);
            let mut node = Node::new(display_name(path), path.to_path_buf(), 0, kind);
            let own = file_size(&md, measure);
            let own_time = file_time(&md, TimeField::Mtime);
            let mut total = own;
            let mut max_time = own_time;
            let mut count = 0u64;
            for entry in entries.filter_map(|e| e.ok()) {
                let child_path = entry.path();
                if skip_entry(&child_path, &entry, filters, measure) {
                    continue;
                }
                let child = walk_child(&child_path, filters, measure, errors);
                if let Some(c) = child {
                    match measure {
                        Measure::FileCount | Measure::Blocks | Measure::Apparent => {
                            total += c.size;
                            count += c.size;
                        }
                        Measure::FileTime(_) => {
                            if c.size > max_time {
                                max_time = c.size;
                            }
                        }
                    }
                    node.children.push(c);
                }
            }
            node.size = match measure {
                Measure::FileCount => count,
                Measure::FileTime(_) => max_time,
                _ => total,
            };
            Some(node)
        }
        Err(e) => {
            // maybe it is a plain file (or a symlink pointing at one)
            let followed = std::fs::metadata(path);
            match followed {
                Ok(m) if m.is_file() => {
                    let kind = resolve_kind(path, &md);
                    let mut node = Node::new(display_name(path), path.to_path_buf(), 0, kind);
                    node.size = match measure {
                        Measure::FileCount => 1,
                        Measure::FileTime(f) => file_time(&md, f),
                        _ => file_size(&md, measure),
                    };
                    Some(node)
                }
                _ => {
                    errors.add(path, &e);
                    None
                }
            }
        }
    }
}

/// Decides whether a child entry should be skipped before walking it.
fn skip_entry(
    child_path: &Path,
    entry: &std::fs::DirEntry,
    filters: &Filters,
    measure: &Measure,
) -> bool {
    let name = entry.file_name().to_string_lossy().to_string();
    if filters.ignore_hidden && name.starts_with('.') {
        return true;
    }
    if filters.ignore_names.iter().any(|n| *n == name) {
        return true;
    }
    let md = match if filters.dereference_links {
        std::fs::metadata(child_path)
    } else {
        std::fs::symlink_metadata(child_path)
    } {
        Ok(m) => m,
        Err(_) => return false,
    };
    if filters.limit_fs {
        use std::os::unix::fs::MetadataExt;
        if md.dev() != filters.root_dev {
            return true;
        }
    }
    if !filters.ignore_regexes.is_empty()
        && filters
            .ignore_regexes
            .iter()
            .any(|r| r.is_match(child_path.to_string_lossy().as_ref()))
    {
        return true;
    }
    if !filters.include_regexes.is_empty()
        && !filters
            .include_regexes
            .iter()
            .any(|r| r.is_match(child_path.to_string_lossy().as_ref()))
    {
        if !md.is_dir() {
            return true;
        }
    }
    if md.is_dir() {
        return false;
    }
    if !filters.time_filters.is_empty() && !time_matches(&md, filters) {
        return true;
    }
    if let Some(min) = filters.min_size {
        if let Measure::Apparent | Measure::Blocks = measure {
            if file_size(&md, measure) <= min {
                return true;
            }
        }
    }
    false
}

fn time_matches(md: &std::fs::Metadata, filters: &Filters) -> bool {
    use std::os::unix::fs::MetadataExt;
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let now_days = now.div_euclid(86400);
    for (field, n, sign) in &filters.time_filters {
        let secs = match field {
            TimeField::Mtime => md.mtime(),
            TimeField::Atime => md.atime(),
            TimeField::Ctime => md.ctime(),
        };
        let file_days = secs.div_euclid(86400);
        let diff = now_days - file_days;
        let target = n + 1;
        let ok = match sign {
            TimeSign::Plus => diff > target,
            TimeSign::Exact => diff == target,
            TimeSign::Minus => diff < target,
        };
        if !ok {
            return false;
        }
    }
    true
}

fn walk_child(
    child_path: &Path,
    filters: &Filters,
    measure: &Measure,
    errors: &mut WalkErrors,
) -> Option<Node> {
    let md = if filters.dereference_links {
        std::fs::metadata(child_path)
    } else {
        std::fs::symlink_metadata(child_path)
    };
    let md = match md {
        Ok(m) => m,
        Err(e) => {
            errors.add(child_path, &e);
            return None;
        }
    };
    let is_dir = md.is_dir();
    if is_dir {
        match std::fs::read_dir(child_path) {
            Ok(entries) => {
                let kind = resolve_kind(child_path, &md);
                let mut node =
                    Node::new(display_name(child_path), child_path.to_path_buf(), 0, kind);
                let own = file_size(&md, measure);
                let own_time = file_time(&md, TimeField::Mtime);
                let mut total = own;
                let mut max_time = own_time;
                let mut count = 0u64;
                for entry in entries.filter_map(|e| e.ok()) {
                    let sub_path = entry.path();
                    if skip_entry(&sub_path, &entry, filters, measure) {
                        continue;
                    }
                    if let Some(c) = walk_child(&sub_path, filters, measure, errors) {
                        match measure {
                            Measure::FileCount | Measure::Blocks | Measure::Apparent => {
                                total += c.size;
                                count += c.size;
                            }
                            Measure::FileTime(_) => {
                                if c.size > max_time {
                                    max_time = c.size;
                                }
                            }
                        }
                        node.children.push(c);
                    }
                }
                node.size = match measure {
                    Measure::FileCount => count,
                    Measure::FileTime(_) => max_time,
                    _ => total,
                };
                Some(node)
            }
            Err(e) => {
                errors.add(child_path, &e);
                None
            }
        }
    } else {
        let kind = resolve_kind(child_path, &md);
        let size = match measure {
            Measure::FileCount => 1,
            Measure::FileTime(f) => file_time(&md, f),
            _ => file_size(&md, measure),
        };
        Some(Node::new(
            display_name(child_path),
            child_path.to_path_buf(),
            size,
            kind,
        ))
    }
}

fn display_name(path: &Path) -> String {
    match path.file_name() {
        Some(n) => n.to_string_lossy().to_string(),
        None => path.to_string_lossy().to_string(),
    }
}

/// Removes nodes that do not match any of the -e filters (and are not needed
/// as ancestors of matching nodes). Sizes are recomputed.
pub fn prune_includes(node: &mut Node, filters: &Filters, measure: &Measure) -> bool {
    let matched = !filters.include_regexes.is_empty()
        && filters
            .include_regexes
            .iter()
            .any(|r| r.is_match(node.path.to_string_lossy().as_ref()));
    let mut kept: Vec<Node> = Vec::new();
    for child in node.children.drain(..) {
        let mut c = child;
        if prune_includes(&mut c, filters, measure) {
            kept.push(c);
        }
    }
    node.children = kept;
    let own = node.own_size;
    if matched || !node.children.is_empty() {
        // recompute size
        node.size = match measure {
            Measure::FileCount => node.children.iter().map(|c| c.size).sum(),
            Measure::FileTime(_) => node
                .children
                .iter()
                .map(|c| c.size)
                .fold(own_time, |a, b| a.max(b)),
            Measure::Blocks | Measure::Apparent => {
                own + node.children.iter().map(|c| c.size).sum::<u64>()
            }
        };
        true
    } else {
        false
    }
}
