use crate::node::{Kind, Node};
use crate::utils::{format_data, format_timestamp, OutputFormat};
use crate::opts::{DisplayOpts, Measure, TimeField};

const TREE_BRANCH: &str = "\u{251c}\u{2500}\u{2500}"; // |--
const TREE_FIRST_UP: &str = "\u{250c}\u{2500}\u{2500}"; // ,--
const TREE_FIRST_DOWN: &str = "\u{2514}\u{2500}\u{2500}"; // `--
const BAR_UP: char = '\u{2534}'; // vertical up (children printed above)
const BAR_DOWN: char = '\u{252c}'; // vertical down (children printed below)
const VERT: &str = "\u{2502} ";
const SP2: &str = "  ";
const BAR_V: &str = "\u{2502}";
const FULL: char = '\u{2588}';
const DARK: char = '\u{2593}';
const MED: char = '\u{2592}';
const LIGHT: char = '\u{2591}';

/// A node of the display tree: the walk tree filtered and sorted.
pub struct SNode<'a> {
    pub node: &'a Node,
    pub children: Vec<SNode<'a>>,
    pub real_depth: usize,
    /// whether this node is the last child of its parent (descending order)
    pub last_in_desc: bool,
    /// whether this node is the biggest child of its parent
    pub is_biggest: bool,
    /// whether this node survives the display pruning
    pub kept: bool,
}

/// Build the sorted (descending) tree, computing depths.
pub fn build_sorted(node: &'a Node, real_depth: usize, is_root: bool) -> SNode<'a> {
    let mut children: Vec<SNode> = node
        .children
        .iter()
        .map(|c| build_sorted(c, real_depth + 1, false))
        .collect();
    // stable sort descending by size
    children.sort_by(|a, b| b.node.size.cmp(&a.node.size));
    let last = children.len().saturating_sub(1);
    for (i, c) in children.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
    SNode {
        node,
        children,
        real_depth,
        last_in_desc: true,
        is_biggest: true,
        kept: is_root,
    }
}

/// Mark the nodes to keep: the top `n` biggest nodes (excluding the root) and
/// all their ancestors.
pub fn mark_kept(node: &mut SNode<'a>, order: &mut Vec<*const Node>, n: usize) {
    order.push(node.node as *const Node);
    for c in node.children.iter_mut() {
        mark_kept(c, order, n);
    }
}

pub fn apply_keep(node: &mut SNode<'a>, keep: &std::collections::HashSet<*const Node>) {
    node.kept = keep.contains(&(node.node as *const Node));
    for c in node.children.iter_mut() {
        apply_keep(c, keep);
    }
}

pub fn prune_tree(node: &mut SNode<'a>) -> bool {
    let mut kept_children: Vec<SNode<'a>> = Vec::new();
    for c in node.children.drain(..) {
        let mut c = c;
        if prune_tree(&mut c) {
            kept_children.push(c);
        }
    }
    let last = kept_children.len().saturating_sub(1);
    for (i, c) in kept_children.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
    node.children = kept_children;
    node.kept
}

/// One output row.
pub struct Row<'a> {
    pub node: &'a Node,
    pub depth: usize,
    pub real_depth: usize,
    pub indent: Vec<bool>,
    pub last_in_desc: bool,
    pub has_children: bool,
    pub is_biggest: bool,
}

/// Emit rows in display order. reverse=false gives post-order (children first),
/// reverse=true gives pre-order (parent first).
pub fn emit_rows(node: &SNode<'a>, indent: Vec<bool>, reverse: bool, out: &mut Vec<Row<'a>>) {
    let has_children = !node.children.is_empty();
    if reverse {
        out.push(Row {
            node: node.node,
            depth: indent.len(),
            real_depth: node.real_depth,
            indent: indent.clone(),
            last_in_desc: node.last_in_desc,
            has_children,
            is_biggest: node.is_biggest,
        });
        for c in node.children.iter() {
            let mut ind = indent.clone();
            ind.push(!c.last_in_desc);
            emit_rows(c, ind, reverse, out);
        }
    } else {
        for c in node.children.iter().rev() {
            let mut ind = indent.clone();
            ind.push(!c.last_in_desc);
            emit_rows(c, ind, reverse, out);
        }
        out.push(Row {
            node: node.node,
            depth: indent.len(),
            real_depth: node.real_depth,
            indent: indent.clone(),
            last_in_desc: node.last_in_desc,
            has_children,
            is_biggest: node.is_biggest,
        });
    }
}

/// ANSI colours.
pub struct Colors {
    pub enabled: bool,
}

impl Colors {
    pub fn red(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[31m{}\x1b[0m", s)
        } else {
            s.to_owned()
        }
    }
    pub fn name(&self, s: &str, kind: Kind, exec: bool, is_total: bool) -> String {
        if !self.enabled || is_total {
            return s.to_owned();
        }
        match kind {
            Kind::Folder => format!("\x1b[1;34m{}\x1b[0m", s),
            Kind::File if exec => format!("\x1b[1;32m{}\x1b[0m", s),
            Kind::Fifo => format!("\x1b[33m{}\x1b[0m", s),
            Kind::Socket => format!("\x1b[1;35m{}\x1b[0m", s),
            Kind::CharDev | Kind::BlockDev => format!("\x1b[33m{}\x1b[0m", s),
            _ => s.to_owned(),
        }
    }
}

fn size_str(node: &Node, opts: &DisplayOpts) -> String {
    match opts.measure {
        Measure::FileTime(_) => format_timestamp(node.size as i64),
        _ => format_data(node.size, opts.output_format),
    }
}

/// Compute the layout: size column width and the column where bars start.
pub fn compute_layout(rows: &[Row], root_size: u64, opts: &DisplayOpts) -> Layout {
    let mut size_width = 0usize;
    for r in rows.iter() {
        let l = size_str(r.node, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    if !opts.skip_total {
        let l = size_str_of_root(root_size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    let mut bar_left = 0usize;
    for r in rows.iter() {
        let end = size_width + 5 + 2 * r.real_depth + r.node.name.chars().count();
        if end > bar_left {
            bar_left = end;
        }
    }
    let bar_width = if opts.terminal_width > 7 && bar_left + 7 < opts.terminal_width {
        opts.terminal_width - 7 - bar_left
    } else {
        0
    };
    Layout {
        size_width,
        bar_left,
        bar_width,
        max_name_len: 0,
    }
}

fn size_str_of_root(size: u64, opts: &DisplayOpts) -> String {
    match opts.measure {
        Measure::FileTime(_) => format_timestamp(size as i64),
        _ => format_data(size, opts.output_format),
    }
}

pub struct Layout {
    pub size_width: usize,
    pub bar_left: usize,
    pub bar_width: usize,
}

/// Print the tree.
pub fn print_tree(rows: &[Row<'a>], layout: &Layout, opts: &DisplayOpts, colors: &Colors) {
    let reverse = opts.reverse;
    for r in rows.iter() {
        let name_len = r.node.name.chars().count();
        // indent
        let mut prefix = String::new();
        for f in r.indent.iter() {
            if *f {
                prefix.push_str(VERT);
            } else {
                prefix.push_str(SP2);
            }
        }
        // branch
        let branch = if r.last_in_desc {
            if reverse {
                TREE_FIRST_DOWN
            } else {
                TREE_FIRST_UP
            }
        } else {
            TREE_BRANCH
        };
        let branch = if r.has_children {
            let connector = if reverse { BAR_DOWN } else { BAR_UP };
            format!("{}\u{2500}{}", &branch[0..branch.chars().count() - 1], connector)
        } else {
            branch.to_string()
        };
        prefix.push_str(&branch);
        let name_start = layout.size_width + 5 + 2 * r.depth;
        let mut avail = opts.terminal_width.saturating_sub(name_start);
        if layout.bar_width >= 2 {
            avail = layout.bar_left - name_start;
        } else if avail < 2 {
            panic!("Terminal width not wide enough to draw directory tree");
        }
        let mut name = r.node.name.clone();
        if name_len > avail {
            let keep = avail - 2;
            name = r.node.name.chars().take(keep).collect::<String>() + "..";
        }
        let name_field_len = if layout.bar_width >= 2 {
            layout.bar_left - name_start
        } else {
            name.chars().count()
        };
        let mut name_field = String::new();
        name_field.push_str(&name);
        if layout.bar_width >= 2 {
            for _ in name.chars().count()..name_field_len {
                name_field.push(' ');
            }
        }
        let colored_name = colors.name(
            &name_field,
            r.node.kind,
            r.node.exec,
            r.node.is_total,
        );
        let size = size_str(r.node, opts);
        let size_colored = if r.is_biggest || r.node.is_root {
            colors.red(&size)
        } else {
            size.clone()
        };
        let mut line = String::new();
        line.push_str(&format!("{:>width$}", size_colored, width = layout.size_width + count_escapes(&size_colored)));
        line.push(' ');
        line.push_str(&prefix);
        line.push(' ');
        line.push_str(&colored_name);
        if layout.bar_width >= 2 {
            let bar = build_bar(r, layout, opts);
            line.push_str(BAR_V);
            line.push_str(&bar);
            line.push_str(BAR_V);
            let pct = percent(r.node.size, root_size);
            line.push_str(&format!("{:>4}%", pct));
        }
        println!("{}", line);
    }
}
RSEOF
echo ok"}

