/// Compute the layout: size column width and the column where bars start.
pub fn compute_layout(rows: &[Row], root_size: u64, opts: &DisplayOpts) -> Layout {
    let mut size_width = 0usize;
    for r in rows.iter() {
        let l = size_str(r.node, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    if !opts.skip_total {
        let l = size_str_of_root(root_size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    let mut bar_left = 0usize;
    for r in rows.iter() {
        let end = size_width + 5 + 2 * r.real_depth + r.node.name.chars().count();
        if end > bar_left {
            bar_left = end;
        }
    }
    let bar_width = if opts.terminal_width > 7 && bar_left + 7 < opts.terminal_width {
        opts.terminal_width - 7 - bar_left
    } else {
