/// Print the tree.
pub fn print_tree(rows: &[Row<'a>], layout: &Layout, opts: &DisplayOpts, colors: &Colors) {
    let reverse = opts.reverse;
    for r in rows.iter() {
        let name_len = r.node.name.chars().count();
        // indent
        let mut prefix = String::new();
        for f in r.indent.iter() {
            if *f {
                prefix.push_str(VERT);
            } else {
                prefix.push_str(SP2);
            }
        }
        // branch
        let branch = if r.last_in_desc {
            if reverse {
                TREE_FIRST_DOWN
            } else {
                TREE_FIRST_UP
            }
        } else {
            TREE_BRANCH
