        let name_start = layout.size_width + 5 + 2 * r.depth;
        let mut avail = opts.terminal_width.saturating_sub(name_start);
        if layout.bar_width >= 2 {
            avail = layout.bar_left - name_start;
        } else if avail < 2 {
            panic!("Terminal width not wide enough to draw directory tree");
        }
        let mut name = r.node.name.clone();
        if name_len > avail {
            let keep = avail - 2;
            name = r.node.name.chars().take(keep).collect::<String>() + "..";
        }
        let name_field_len = if layout.bar_width >= 2 {
            layout.bar_left - name_start
        } else {
            name.chars().count()
        };
        let mut name_field = String::new();
        name_field.push_str(&name);
        if layout.bar_width >= 2 {
