            Kind::CharDev | Kind::BlockDev => format!("\x1b[33m{}\x1b[0m", s),
            _ => s.to_owned(),
        }
    }
}

pub fn size_str(size: u64, opts: &DisplayOpts) -> String {
    match opts.measure {
        Measure::FileTime(_) => format_timestamp(size as i64),
        _ => format_data(size, opts.output_format),
    }
}

pub struct Layout {
    pub size_width: usize,
    pub bar_left: usize,
    pub bar_width: usize,
    pub max_name_len: usize,
}

/// Compute the layout: the size column width and the column where the bars start.
pub fn compute_layout(rows: &[Row], root_size: u64, opts: &DisplayOpts) -> Layout {
    let mut size_width = 0usize;
    for r in rows.iter() {
        let l = size_str(r.node.size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    if !opts.skip_total {
        let l = size_str(root_size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    let depth_extra = if opts.measure_is_filetime() { 4 } else { 5 };
    let mut bar_left = 0usize;
    for r in rows.iter() {
        let end = size_width + depth_extra + 2 * r.real_depth + r.node.name.chars().count();
        if end > bar_left {
            bar_left = end;
        }
    }
    let bar_width = if opts.terminal_width > bar_left + 7 {
        opts.terminal_width - 7 - bar_left
    } else {
        0
    };
    let max_name_len = rows
        .iter()
        .map(|r| r.node.name.chars().count())
        .max()
        .unwrap_or(0);
    Layout {
        size_width,
        bar_left,
        bar_width,
        max_name_len,
    }
}

fn build_bar(r: &Row, layout: &Layout, opts: &DisplayOpts, root_size: u64) -> String {
    let bar_width = layout.bar_width;
    if bar_width < 2 {
        return String::new();
    }
    let scale = bar_width - 1;
    let total = if root_size == 0 { 1 } else { root_size };
    let fill = |size: u64| -> usize {
        let f = size * scale / total + 1;
        if f > scale {
            scale
        } else {
            f as usize
        }
    };
    let mut out = String::new();
    let node_fill = fill(r.node.size);
    for _ in 0..node_fill {
        out.push(FULL);
    }
    // ancestors at real depth 3, 2, 1 in that order (ascending positions)
    let levels: [(usize, char); 3] = [(2, DARK), (1, MED), (0, LIGHT)];
    let mut prev = node_fill;
    for (idx, shade) in levels.iter() {
        if let Some(sz) = r.ancestors[*idx] {
            let end = fill(sz);
            if end > prev {
                for _ in prev..end {
                    out.push(*shade);
                }
                prev = end;
            }
        }
    }
    while prev < bar_width {
        out.push(' ');
        prev += 1;
    }
    let _ = opts;
    out
}

fn percent(size: u64, total: u64) -> u64 {
    if total == 0 {
        return 0;
    }
    let p = size as f64 * 100.0 / total as f64;
    let rounded = format!("{:.0}", p);
    rounded.parse::<u64>().unwrap_or(0)
}

/// Print the tree (bars mode / no-bars mode / filetime mode).
pub fn print_tree(rows: &[Row<'a>], layout: &Layout, opts: &DisplayOpts, colors: &Colors, root_size: u64) {
    let reverse = opts.reverse;
    for r in rows.iter() {
        let name_len = r.node.name.chars().count();
        let mut prefix = String::new();
        for f in r.indent.iter() {
            if *f {
                prefix.push_str(VERT);
            } else {
                prefix.push_str(SP2);
            }
        }
        let head = if r.last_in_desc {
            if reverse {
                TREE_FIRST_DOWN
            } else {
                TREE_FIRST_UP
            }
        } else {
            TREE_BRANCH
        };
        let connector = if r.has_children {
            if reverse {
                BAR_DOWN
            } else {
                '\u{2534}'
            }
        } else {
            '\u{2500}'
        };
        prefix.push_str(head);
        prefix.push(connector);
        let name_start = layout.size_width + 5 + 2 * r.depth;
        let mut avail = opts.terminal_width.saturating_sub(name_start);
        let with_bar = layout.bar_width >= 2 && !opts.no_bars && !opts.measure_is_filetime();
        if with_bar {
            avail = layout.bar_left - name_start;
        } else if avail < 2 {
            panic!("Terminal width not wide enough to draw directory tree");
        }
        let mut name = r.node.name.clone();
        if name_len > avail {
            let keep = avail - 2;
            name = r.node.name.chars().take(keep).collect::<String>() + "..";
        }
        let field_len = if with_bar {
            layout.bar_left - name_start
        } else {
            name.chars().count()
        };
        let mut name_field = name.clone();
        for _ in name.chars().count()..field_len {
            name_field.push(' ');
        }
        let colored_name = colors.name(&name_field, r.node.kind, r.node.exec, r.node.is_total);
        let size = size_str(r.node.size, opts);
        let padded_size = format!("{:>width$}", size, width = layout.size_width);
        let colored_size = if r.is_biggest || r.real_depth == 0 {
