            line.push_str(BAR_V);
            line.push_str(&bar);
            line.push_str(BAR_V);
            let pct = percent(r.node.size, root_size);
            line.push_str(&format!("{:>4}%", pct));
        }
        println!("{}", line);
    }
}

/// Print in screen reader mode.
pub fn print_screen_reader(rows: &[Row<'a>], layout: &Layout, opts: &DisplayOpts, colors: &Colors, root_size: u64) {
    let name_width = layout.max_name_len + 1;
