use std::collections::HashSet;
use crate::node::{Kind, Node};
use crate::utils::{format_data, format_timestamp, OutputFormat};
use crate::opts::{DisplayOpts, Measure};

const TREE_BRANCH: &str = "\u{251c}\u{2500}"; // |-
const TREE_FIRST_UP: &str = "\u{250c}\u{2500}"; // ,-
const TREE_FIRST_DOWN: &str = "\u{2514}\u{2500}"; // `-
const VERT: &str = "\u{2502} ";
const SP2: &str = "  ";
const BAR_V: &str = "\u{2502}";
const FULL: char = '\u{2588}';
const DARK: char = '\u{2593}';
const MED: char = '\u{2592}';
const LIGHT: char = '\u{2591}';

/// A node of the display tree: the walk tree filtered, sorted descending.
pub struct SNode<'a> {
    pub node: &'a Node,
    pub children: Vec<SNode<'a>>,
    pub real_depth: usize,
    /// whether this node is the last child of its parent (descending order)
    pub last_in_desc: bool,
    /// whether this node is the biggest child of its parent
    pub is_biggest: bool,
    /// whether this node survives the display pruning
    pub kept: bool,
}

pub fn build_sorted(node: &'a Node, real_depth: usize) -> SNode<'a> {
    let mut children: Vec<SNode> = node
        .children
        .iter()
        .map(|c| build_sorted(c, real_depth + 1))
        .collect();
    children.sort_by(|a, b| b.node.size.cmp(&a.node.size));
    let last = children.len().saturating_sub(1);
    for (i, c) in children.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
    SNode {
        node,
        children,
        real_depth,
        last_in_desc: true,
        is_biggest: true,
        kept: real_depth == 0,
    }
}

pub fn apply_keep(node: &mut SNode<'a>, keep: &HashSet<*const Node>) {
    if real_depth_is_root(node) {
        node.kept = true;
    } else {
        node.kept = keep.contains(&(node.node as *const Node));
    }
    for c in node.children.iter_mut() {
        apply_keep(c, keep);
    }
}

fn real_depth_is_root(node: &SNode) -> bool {
    node.real_depth == 0
}

pub fn prune_tree(node: &mut SNode<'a>) -> bool {
    let mut kept_children: Vec<SNode<'a>> = Vec::new();
    for c in node.children.drain(..) {
        let mut c = c;
        if prune_tree(&mut c) {
            kept_children.push(c);
        }
    }
    let last = kept_children.len().saturating_sub(1);
    for (i, c) in kept_children.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
    node.children = kept_children;
    node.kept
}

/// One output row.
pub struct Row<'a> {
    pub node: &'a Node,
    /// depth in the displayed tree (0 = topmost displayed level)
    pub depth: usize,
    /// depth counting the root even when it is not displayed
    pub real_depth: usize,
    /// for each displayed ancestor level (top down): whether that ancestor has
    /// siblings still to be drawn on the other side
    pub indent: Vec<bool>,
    pub last_in_desc: bool,
    pub has_children: bool,
    pub is_biggest: bool,
    /// sizes of the ancestors at real depth 1, 2 and 3
    pub ancestors: [Option<u64>; 3],
}

pub fn emit_rows(
    node: &SNode<'a>,
    indent: Vec<bool>,
    ancestors: [Option<u64>; 3],
    reverse: bool,
    out: &mut Vec<Row<'a>>,
) {
    let has_children = !node.children.is_empty();
    let row = |ind: Vec<bool>, anc: [Option<u64>; 3]| Row {
        node: node.node,
        depth: ind.len(),
        real_depth: node.real_depth,
        indent: ind,
        last_in_desc: node.last_in_desc,
        has_children,
        is_biggest: node.is_biggest,
        ancestors: anc,
    };
    let child_ancestors = |anc: &[Option<u64>; 3], c: &SNode<'a>| -> [Option<u64>; 3] {
        let mut a = [None; 3];
        // shift: the parent becomes the depth-1 ancestor
        a[0] = Some(c.node.size);
        a[1] = anc[0];
        a[2] = anc[1];
        a
    };
    if reverse {
        let _ = child_ancestors;
        out.push(row(indent.clone(), ancestors));
        for c in node.children.iter() {
            let mut ind = indent.clone();
            ind.push(!c.last_in_desc);
            let anc = shift_ancestors(&ancestors, c.node.size);
            emit_rows(c, ind, anc, reverse, out);
        }
    } else {
        for c in node.children.iter().rev() {
            let mut ind = indent.clone();
            ind.push(!c.last_in_desc);
            let anc = shift_ancestors(&ancestors, c.node.size);
            emit_rows(c, ind, anc, reverse, out);
        }
        out.push(row(indent.clone(), ancestors));
    }
}

fn shift_ancestors(anc: &[Option<u64>; 3], parent_size: u64) -> [Option<u64>; 3] {
    [Some(parent_size), anc[0], anc[1]]
}

/// ANSI colours.
pub struct Colors {
    pub enabled: bool,
}

impl Colors {
    pub fn red(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[31m{}\x1b[0m", s)
        } else {
            s.to_owned()
        }
    }
    pub fn name(&self, s: &str, kind: Kind, exec: bool, is_total: bool) -> String {
        if !self.enabled || is_total {
            return s.to_owned();
        }
        match kind {
            Kind::Folder => format!("\x1b[1;34m{}\x1b[0m", s),
            Kind::File if exec => format!("\x1b[1;32m{}\x1b[0m", s),
            Kind::Fifo => format!("\x1b[33m{}\x1b[0m", s),
            Kind::Socket => format!("\x1b[1;35m{}\x1b[0m", s),
            Kind::CharDev | Kind::BlockDev => format!("\x1b[33m{}\x1b[0m", s),
            _ => s.to_owned(),
        }
    }
}

pub fn size_str(size: u64, opts: &DisplayOpts) -> String {
    match opts.measure {
        Measure::FileTime(_) => format_timestamp(size as i64),
        _ => format_data(size, opts.output_format),
    }
}

pub struct Layout {
    pub size_width: usize,
    pub bar_left: usize,
    pub bar_width: usize,
    pub max_name_len: usize,
}

/// Compute the layout: the size column width and the column where the bars start.
pub fn compute_layout(rows: &[Row], root_size: u64, opts: &DisplayOpts) -> Layout {
    let mut size_width = 0usize;
    for r in rows.iter() {
        let l = size_str(r.node.size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    if !opts.skip_total {
        let l = size_str(root_size, opts).chars().count();
        if l > size_width {
            size_width = l;
        }
    }
    let depth_extra = if opts.measure_is_filetime() { 4 } else { 5 };
    let mut bar_left = 0usize;
    for r in rows.iter() {
        let end = size_width + depth_extra + 2 * r.real_depth + r.node.name.chars().count();
        if end > bar_left {
            bar_left = end;
        }
    }
    let bar_width = if opts.terminal_width > bar_left + 7 {
        opts.terminal_width - 7 - bar_left
    } else {
        0
    };
    let max_name_len = rows
        .iter()
        .map(|r| r.node.name.chars().count())
        .max()
        .unwrap_or(0);
    Layout {
        size_width,
        bar_left,
        bar_width,
        max_name_len,
    }
}

fn build_bar(r: &Row, layout: &Layout, opts: &DisplayOpts, root_size: u64) -> String {
    let bar_width = layout.bar_width;
    if bar_width < 2 {
        return String::new();
    }
    let scale = bar_width - 1;
    let total = if root_size == 0 { 1 } else { root_size };
    let fill = |size: u64| -> usize {
        let f = size * scale / total + 1;
        if f > scale {
            scale
        } else {
            f as usize
        }
    };
    let mut out = String::new();
    let node_fill = fill(r.node.size);
    for _ in 0..node_fill {
        out.push(FULL);
    }
    // ancestors at real depth 3, 2, 1 in that order (ascending positions)
    let levels: [(usize, char); 3] = [(2, DARK), (1, MED), (0, LIGHT)];
    let mut prev = node_fill;
    for (idx, shade) in levels.iter() {
        if let Some(sz) = r.ancestors[*idx] {
            let end = fill(sz);
            if end > prev {
                for _ in prev..end {
                    out.push(*shade);
                }
                prev = end;
            }
        }
    }
    while prev < bar_width {
        out.push(' ');
        prev += 1;
    }
    let _ = opts;
    out
}

fn percent(size: u64, total: u64) -> u64 {
    if total == 0 {
        return 0;
    }
    let p = size as f64 * 100.0 / total as f64;
    let rounded = format!("{:.0}", p);
    rounded.parse::<u64>().unwrap_or(0)
}

