use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

use crate::config::{parse_min_size, ConfigValues};
use crate::display::{
    build_sorted, apply_keep, prune_tree, emit_rows, compute_layout, print_tree, print_screen_reader,
    print_json, Colors, SNode,
};
use crate::node::{Node, Kind, TimeField, TimeSign, WalkErrors};
use crate::opts::{DisplayOpts, Measure, WalkOpts};
use crate::utils::OutputFormat;

/// Everything the display needs, after merging the config and the arguments.
pub struct Options {
    pub display: DisplayOpts,
    pub walk: WalkOpts,
    pub measure: Measure,
    pub root_size_for_layout: u64,
}

pub fn merge_output_format(s: Option<&str>) -> OutputFormat {
    match s {
        Some(s) => OutputFormat::from_str(s).unwrap_or(OutputFormat::K),
        None => OutputFormat::K,
    }
}

/// Group files by extension (-t mode).
pub fn build_type_groups(roots: &[Node], total_size: u64) -> Node {
    let mut groups: HashMap<String, u64> = HashMap::new();
    for root in roots {
        collect_types(root, &mut groups);
    }
    let mut total = Node::new(
        "(total)".to_string(),
        PathBuf::new(),
        total_size,
        Kind::File,
    );
    total.is_root = true;
    total.is_total = true;
    for (name, size) in groups {
        let mut n = Node::new(name, PathBuf::new(), size, Kind::File);
        n.is_root = false;
        total.children.push(n);
    }
    total
}

fn collect_types(node: &Node, groups: &mut HashMap<String, u64>) {
    if node.kind == Kind::Folder {
        for c in node.children.iter() {
            collect_types(c, groups);
        }
    } else {
        let ext = match Path::new(&node.path).extension() {
            Some(e) => format!(".{}", e.to_string_lossy()),
            None => "(no extension)".to_string(),
        };
        *groups.entry(ext).or_insert(0) += node.size;
    }
}

/// Keep only the top `n` biggest nodes (plus the root and ancestors).
pub fn limit_nodes(root: &mut SNode, n: usize) {
    let mut order: Vec<*const Node> = Vec::new();
    collect_order(root, &mut order);
    let mut sized: Vec<(*const Node, u64)> = order.iter().map(|p| (*p, unsafe { (**p).size })).collect();
    sized.sort_by(|a, b| b.1.cmp(&a.1));
    let mut keep: HashSet<*const Node> = HashSet::new();
    for (p, _) in sized.iter().take(n) {
        keep.insert(*p);
    }
    // ensure ancestors of kept nodes are kept
    mark_ancestors(root, &keep, &mut HashSet::new());
    apply_keep(root, &keep);
    // also mark the ancestors
    set_ancestors_kept(root);
    prune_tree(root);
}

fn collect_order(node: &SNode, out: &mut Vec<*const Node>) {
    out.push(node.node as *const Node);
    for c in node.children.iter() {
        collect_order(c, out);
    }
}

unsafe fn mark_ancestors(node: &SNode, keep: &HashSet<*const Node>, seen: &mut HashSet<*const Node>) {
    for c in node.children.iter() {
        mark_ancestors(c, keep, seen);
    }
    let p = node.node as *const Node;
    if !seen.insert(p) {
        return;
    }
    if keep.contains(&p) {
        node.kept = true;
        // propagate up handled by caller
    }
}

fn set_ancestors_kept(node: &mut SNode) {
    let mut any_child_kept = false;
    for c in node.children.iter_mut() {
        set_ancestors_kept(c);
        if c.kept {
            any_child_kept = true;
        }
    }
    if any_child_kept {
        node.kept = true;
    }
}
RSEOF
echo ok"}

