/// Marks the nodes that survive the -n / -d / collapse pruning and prunes the
/// tree.
pub fn limit_tree(root: &mut SNode, n: usize, max_depth: Option<usize>, collapse: &[String]) {
    // 1. apply the collapse filter
    collapse_filter(root, collapse);
    // 2. collect the nodes in pre-order (children sorted descending)
    let mut order: Vec<(*const Node, u64)> = Vec::new();
    collect_order(root, &mut order);
    // 3. sort by size descending, stable
    order.sort_by(|a, b| b.1.cmp(&a.1));
    let mut keep: HashSet<*const Node> = HashSet::new();
    let mut count = 0usize;
    for (p, _) in order.iter() {
        if count >= n {
            break;
        }
        keep.insert(*p);
        count += 1;
    }
    // 4. depth limit is enforced while marking
    mark(root, &keep, max_depth);
    prune_tree(root);
}

fn collect_order(node: &SNode, out: &mut Vec<(*const Node, u64)>) {
    out.push((node.node as *const Node, node.node.size));
    for c in node.children.iter() {
        collect_order(c, out);
