}

fn collapse_filter(node: &mut SNode, collapse: &[String]) {
    if !collapse.is_empty() && collapse.iter().any(|c| *c == node.node.name) {
        node.children.clear();
        return;
    }
    for c in node.children.iter_mut() {
        collapse_filter(c, collapse);
    }
}

fn mark(node: &mut SNode, keep: &HashSet<*const Node>, max_depth: Option<usize>) -> bool {
    let self_kept = node.real_depth == 0 || keep.contains(&(node.node as *const Node));
    let depth_ok = match max_depth {
        Some(d) => node.real_depth <= d,
        None => true,
    };
    let mut any_child = false;
    if depth_ok {
        for c in node.children.iter_mut() {
            if mark(c, keep, max_depth) {
                any_child = true;
            }
        }
    } else {
        node.children.clear();
    }
    node.kept = (self_kept && depth_ok) || any_child;
    if !node.kept {
        node.children.clear();
    }
    node.kept
}

pub fn keep_mark(node: &mut SNode, keep: &HashSet<*const Node>) {
    apply_keep(node, keep);
}
