use std::collections::HashSet;
use std::path::{Path, PathBuf};

use crate::config::{self, ConfigValues};
use crate::display::{self, Colors, Layout, SNode};
use crate::flow::build_type_groups;
use crate::node::{self, Kind, Measure, Node, TimeField, TimeSign, WalkErrors};
use crate::opts::{DisplayOpts, WalkOpts};
use crate::utils::OutputFormat;

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| {
            Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
        })
        .unwrap_or_else(|| "dust".to_string())
}

/// Read a config file from the location implied by the arguments.
fn read_config(matches: &clap::ArgMatches) -> Option<ConfigValues> {
    if let Some(p) = matches.get_one::<PathBuf>("config") {
        if p.exists() {
            let cfg = config::read_config_file(p, true);
            return cfg;
        } else {
            eprintln!("Config file \"{}\" doesn't exists", p.display());
            return None;
        }
    }
    let home = std::env::var_os("HOME").map(PathBuf::from);
    if let Some(h) = &home {
        let mut p = h.clone();
        p.push(".dust.toml");
        if p.exists() {
            if let Some(c) = config::read_config_file(&p, true) {
                return Some(c);
            }
        }
        let mut q = h.clone();
        q.push(".config");
        q.push("dust");
        q.push("config.toml");
        if q.exists() {
            if let Some(c) = config::read_config_file(&q, true) {
                return Some(c);
            }
        }
    }
    None
}

/// Parses the -z / --min-size argument.
fn parse_min_size(spec: Option<&str>) -> Option<u64> {
    let s = spec?;
    let trimmed = s.trim();
    let num: String = trimmed.chars().take_while(|c| c.is_ascii_digit()).collect();
    if num.is_empty() {
        return None;
    }
    let n: u64 = match num.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    let rest: String = trimmed.chars().skip(num.len()).collect();
    let suffix: String = rest.chars().take_while(|c| c.is_ascii_alphabetic()).collect();
    if suffix.is_empty() {
        return Some(n);
    }
    let lower = suffix.to_lowercase();
    let first = match lower.chars().next() {
        Some(c) => c,
        None => return Some(n),
    };
    let exp = match first {
        'b' => 0,
        'k' => 1,
        'm' => 2,
        'g' => 3,
        't' => 4,
        'p' => 5,
        _ => {
            eprintln!("Ignoring invalid min-size: {}", s);
            return None;
        }
    };
    let base = if lower.len() == 1 || lower.contains('i') {
        1024u64
    } else {
        1000u64
    };
    Some(n * base.pow(exp))
}

fn compile_regexes(vals: &[String], invert: bool) -> Vec<regex::Regex> {
    let mut out = Vec::new();
    for v in vals {
        match regex::Regex::new(v) {
            Ok(r) => out.push(r),
            Err(e) => {
                if invert {
                    // silently ignore bad patterns from the ignore file
                } else {
                    eprintln!("Ignoring bad value for regex {:?}", e);
                }
            }
        }
    }
    out
}

fn read_ignore_file(path: &Path) -> Vec<String> {
    let exists = path.exists();
    if exists {
        let file = std::fs::read_to_string(path);
        file.unwrap()
            .lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect()
    } else {
        Vec::new()
    }
}

fn read_paths_file(spec: &str, nul: bool) -> Result<Vec<PathBuf>, std::io::Error> {
    let text = if spec == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s)?;
        s
    } else {
        match std::fs::read_to_string(spec) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("Failed to read file: {}", e);
                return Err(e);
            }
        }
    };
    let mut out = Vec::new();
    if nul {
        for part in text.split('\0') {
            if part.is_empty() {
                continue;
            }
            out.push(PathBuf::from(part));
        }
    } else {
        for line in text.split('\n') {
            let l = line.trim();
            out.push(PathBuf::from(l));
        }
    }
    Ok(out)
}

fn measure(opts: &DisplayOpts, apparent: bool, filecount: bool, filetime: Option<TimeField>) -> Measure {
    if let Some(f) = filetime {
        Measure::FileTime(f)
    } else if filecount {
        Measure::FileCount
    } else if apparent {
        Measure::Apparent
    } else {
        Measure::Blocks
    }
}

fn main() {
    let bin = bin_name();
    let mut cmd = cli(&bin);
    let matches = cmd.get_matches();
    let cfg = read_config(&matches);

    // ---- booleans (config OR command line) ----
    let b = |name: &str, key: Option<bool>| -> bool {
        matches.get_flag(name) || key.unwrap_or(false)
    };
    let full_paths = b("full-paths", cfg.display_full_paths);
    let apparent = b("apparent-size", cfg.display_apparent_size);
    let no_colors = b("no-colors", cfg.no_colors);
    let no_bars = b("no-percent-bars", cfg.no_bars);
    let skip_total = b("skip-total", cfg.skip_total);
    let ignore_hidden = b("ignore-hidden", cfg.ignore_hidden);
    let filecount = b("filecount", cfg.filecount);
    let only_dir = b("only-dir", cfg.only_dir);
    let only_file = b("only-file", cfg.only_file);
    let file_types = b("file-types", cfg.file_types);
    let screen_reader = b("screen-reader", cfg.screen_reader);
    let print_errors = b("print-errors", cfg.print_errors);
    let output_json = b("output-json", cfg.output_json);
    let bars_on_right = b("bars-on-right", cfg.bars_on_right);
    let dereference = b("dereference-links", cfg.dereference_links);
    let limit_fs = b("limit-filesystem", cfg.limit_filesystem);
    let reverse = b("reverse", cfg.reverse);
    let no_progress = b("no-progress", cfg.no_progress);
    let force_colors = b("force-colors", None);

    let width = matches
        .get_one::<usize>("terminal-width")
        .copied()
        .or(cfg.terminal_width);
    let number_of_lines = matches
        .get_one::<usize>("number-of-lines")
        .copied()
        .or(cfg.number_of_lines);
    let depth = matches.get_one::<usize>("depth").copied().or(cfg.depth);
    let threads = matches.get_one::<usize>("threads").copied().or(cfg.threads);
    let stack_size = matches
        .get_one::<usize>("stack-size")
        .copied()
        .or(cfg.stack_size);

    let of = matches
        .get_one::<String>("output-format")
        .cloned()
        .or_else(|| cfg.output_format.clone());
    let output_format = merge_output_format(of.as_deref());

    let filetime_field = matches
        .get_one::<String>("filetime")
        .cloned()
        .or_else(|| cfg.filetime.clone())
        .map(|v| match v.to_lowercase().as_str() {
            "a" => TimeField::Atime,
            "c" => TimeField::Ctime,
            _ => TimeField::Mtime,
        });

    // ---- paths ----
    let mut paths: Vec<PathBuf> = Vec::new();
    if let Some(f0) = matches.get_one::<String>("files0-from") {
        match read_paths_file(f0, true) {
            Ok(v) => paths.extend(v),
            Err(_) => {}
        }
    } else if let Some(ff) = matches.get_one::<String>("files-from") {
        match read_paths_file(ff, false) {
            Ok(v) => paths.extend(v),
            Err(_) => {}
        }
    }
    if paths.is_empty() {
        for p in matches.get_many::<PathBuf>("paths").unwrap_or_default() {
            paths.push(p.clone());
        }
    }
    if paths.is_empty() {
        paths.push(PathBuf::from("."));
    }

    // ---- ignore/include filters ----
    let mut ignore_names: Vec<String> = Vec::new();
    if let Some(v) = matches.get_many::<String>("ignore-directory") {
        for s in v {
            ignore_names.push(s.clone());
        }
    }
    if let Some(v) = &cfg.ignore_directory {
        for s in v {
            ignore_names.push(s.clone());
        }
    }
    let mut invert: Vec<String> = Vec::new();
    if let Some(v) = matches.get_many::<String>("invert-filter") {
        for s in v {
            invert.push(s.clone());
        }
    }
    if let Some(v) = &cfg.invert_filter {
        for s in v {
            invert.push(s.clone());
        }
    }
    let mut ignore_regex_strings: Vec<String> = Vec::new();
    {
        let mut file_ignores: Vec<String> = Vec::new();
        if let Some(v) = matches.get_many::<PathBuf>("ignore-all-in-file") {
            for p in v {
                for line in read_ignore_file(p) {
                    file_ignores.push(line);
                }
            }
        }
        if let Some(v) = &cfg.ignore_all_in_file {
            for p in v {
                for line in read_ignore_file(Path::new(p)) {
                    file_ignores.push(line);
                }
            }
        }
        ignore_regex_strings.extend(invert.iter().cloned());
        ignore_regex_strings.extend(file_ignores);
    }
    let mut include_strings: Vec<String> = Vec::new();
    if let Some(v) = matches.get_many::<String>("filter") {
        for s in v {
            include_strings.push(s.clone());
        }
    }
    if let Some(v) = &cfg.filter {
        for s in v {
            include_strings.push(s.clone());
        }
    }
    let mut collapse: Vec<String> = Vec::new();
    if let Some(v) = matches.get_many::<String>("collapse") {
        for s in v {
            collapse.push(s.clone());
        }
    }
    if let Some(v) = &cfg.collapse {
        for s in v {
            collapse.push(s.clone());
        }
    }

    let mut time_filters: Vec<(TimeField, i64, TimeSign)> = Vec::new();
    if let Some(v) = matches.get_one::<String>("mtime").or(cfg.mtime.as_deref().map(|x| &x.to_string()).map(|x| x)) {
        let (sign, n) = config::parse_time_spec(v);
        time_filters.push((TimeField::Mtime, n, sign));
    }
    if let Some(v) = matches.get_one::<String>("atime") {
        let (sign, n) = config::parse_time_spec(v);
        time_filters.push((TimeField::Atime, n, sign));
    }
    if let Some(v) = matches.get_one::<String>("ctime") {
        let (sign, n) = config::parse_time_spec(v);
        time_filters.push((TimeField::Ctime, n, sign));
    }

    let min_size = parse_min_size(
        matches
            .get_one::<String>("min-size")
            .map(|s| s.as_str())
            .or(cfg.min_size.as_deref()),
    );

    let ignore_regexes = compile_regexes(&ignore_regex_strings, true);
    let include_regexes = compile_regexes(&include_strings, false);

    let mut errors = WalkErrors::new();
    let root_dev = {
        use std::os::unix::fs::MetadataExt;
        std::fs::metadata(&paths[0]).map(|m| m.dev()).unwrap_or(0)
    };

    let walk_opts = WalkOpts {
        ignore_names,
        ignore_regexes,
        include_regexes,
        ignore_hidden,
        min_size,
        time_filters,
        limit_fs,
        root_dev,
        dereference_links: dereference,
    };

    let m = measure(&display_stub(), apparent, filecount, filetime_field);
    let measure = m;

    // ---- walk ----
    let mut roots: Vec<Node> = Vec::new();
    for p in paths.iter() {
        if let Some(n) = node::walk(p, &walk_opts, &measure, &mut errors) {
            let mut n = n;
            n.is_root = true;
            roots.push(n);
        }
    }
    if roots.is_empty() {
        print_errors_out(&errors, print_errors);
        std::process::exit(1);
    }

    // apply -e include filter pruning
    for r in roots.iter_mut() {
        node::prune_includes(r, &walk_opts, &measure);
    }

    let total_size: u64 = roots.iter().map(|r| r.size).sum();
    let root_node: Node = if roots.len() == 1 && !file_types {
        let mut r = std::mem::replace(&mut roots[0], Node::new(String::new(), PathBuf::new(), 0, Kind::File));
        r.is_root = true;
        r
    } else if file_types {
        build_type_groups(&roots, total_size)
    } else {
        let mut t = Node::new("(total)".to_string(), PathBuf::new(), total_size, Kind::File);
        t.is_root = true;
        t.is_total = true;
        t.children = roots;
        t
    };

    print_errors_out(&errors, print_errors);

    let d = display_opts(
        output_format,
        measure,
        no_bars,
        bars_on_right,
        reverse,
        skip_total,
        screen_reader,
        only_dir,
        only_file,
        file_types,
        full_paths,
        width,
        number_of_lines,
        depth,
        output_json,
        collapse,
        filetime_field,
    );
    display::run(&root_node, &d, &errors, print_errors, no_progress, force_colors, no_colors, stack_size);
}
RSEOF
echo ok"}

