/// Read the configuration file, honouring --config and the two default spots.
fn read_config(matches: &clap::ArgMatches) -> Option<ConfigValues> {
    if let Some(p) = matches.get_one::<PathBuf>("config") {
        if p.exists() {
            return config::read_config_file(p, true);
        }
        eprintln!("Config file \"{}\" doesn't exists", p.display());
