        xdg.push("config.toml");
        if xdg.exists() {
            if let Some(c) = config::read_config_file(&xdg, true) {
                return Some(c);
            }
        }
    }
    None
}

/// Parse a human readable size such as "10M", "1KiB" or "1024".
fn parse_min_size(spec: Option<&str>) -> Option<u64> {
    let s = spec?;
    let trimmed = s.trim();
    let num: String = trimmed.chars().take_while(|c| c.is_ascii_digit()).collect();
    if num.is_empty() {
        return None;
    }
    let n: u64 = match num.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    let rest: String = trimmed.chars().skip(num.len()).collect();
    let suffix: String = rest.chars().take_while(|c| c.is_ascii_alphabetic()).collect();
    if suffix.is_empty() {
        return Some(n);
    }
    let lower = suffix.to_lowercase();
    let first = match lower.chars().next() {
        Some(c) => c,
        None => return Some(n),
    };
    let exp = match first {
        'b' => 0,
        'k' => 1,
        'm' => 2,
        'g' => 3,
        't' => 4,
        'p' => 5,
        _ => {
            eprintln!("Ignoring invalid min-size: {}", s);
            return None;
        }
    };
    let base = if lower.len() == 1 || lower.contains('i') {
        1024u64
    } else {
        1000u64
    };
    Some(n * base.pow(exp))
}

/// Compile a list of regular expressions, warning about bad ones.
fn compile_regexes(vals: &[String], from_ignore_file: bool) -> Vec<regex::Regex> {
    let mut out = Vec::new();
    for v in vals {
        match regex::Regex::new(v) {
            Ok(r) => out.push(r),
            Err(e) => {
                if !from_ignore_file {
                    eprintln!("Ignoring bad value for regex {:?}", e);
                }
            }
        }
    }
    out
}

/// Read the newline separated list of patterns to ignore. Missing or unreadable
/// files cause the program to abort, exactly like upstream dust.
fn read_ignore_file(path: &Path) -> Vec<String> {
    let readable = path.exists();
    if readable {
        let file = std::fs::read_to_string(path);
        file.unwrap()
            .lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect()
    } else {
        Vec::new()
    }
}

/// Read the list of input paths from a file (`-` means standard input).
fn read_paths_file(spec: &str, nul_separated: bool) -> Option<Vec<PathBuf>> {
    let text = if spec == "-" {
        let mut s = String::new();
        if std::io::stdin().read_to_string(&mut s).is_err() {
            eprintln!("Failed to read file: No such file or directory (os error 2)");
            return None;
        }
        s
    } else {
        match std::fs::read_to_string(spec) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("Failed to read file: {}", e);
                return None;
            }
        }
    };
    let mut out = Vec::new();
    if nul_separated {
        for part in text.split('\0') {
            if part.is_empty() {
                continue;
            }
            out.push(PathBuf::from(part));
        }
    } else {
        for line in text.split('\n') {
            out.push(PathBuf::from(line.trim()));
        }
    }
    Some(out)
}

fn measure_of(
    apparent: bool,
    filecount: bool,
    filetime: Option<TimeField>,
) -> Measure {
    if let Some(f) = filetime {
        Measure::FileTime(f)
    } else if filecount {
        Measure::FileCount
    } else if apparent {
        Measure::Apparent
    } else {
        Measure::Blocks
    }
}

fn print_errors_out(errors: &WalkErrors, print_errors: bool) {
    if !errors.not_found.is_empty() {
        let v: Vec<String> = errors.not_found.iter().cloned().collect();
        eprintln!("No such file or directory: {}", v.join(", "));
    }
    if !errors.permissions.is_empty() {
        if print_errors {
            let v: Vec<String> = errors.permissions.iter().cloned().collect();
            eprintln!("Did not have permissions for directories: {}", v.join(", "));
        } else {
            eprintln!("Did not have permissions for all directories (add --print-errors to see errors)");
        }
    }
}
