new_run = '''/// Entry point of the display: prune, lay out and print the tree.
pub fn run(root: &Node, opts: &DisplayOpts, colors: &Colors, _stack_size: Option<usize>) {
    let mut sorted = build_sorted(root, 0);
    if opts.only_dir {
        filter_dirs(&mut sorted);
    }
    if opts.only_file {
        filter_files(&mut sorted);
    }
    crate::flow::limit_tree(
        &mut sorted,
        opts.number_of_lines,
        Some(opts.depth),
        &opts.collapse,
    );
    // rows: normally the root is the first/last row, with --skip-total the
    // children become the top level
    let mut rows: Vec<Row> = Vec::new();
    if opts.skip_total {
        let indent: Vec<bool> = Vec::new();
        let ancestors: Vec<(usize, u64)> = vec![(0, root.size)];
        for c in sorted.children.iter() {
            if opts.reverse {
                let mut ind = indent.clone();
                ind.push(!c.last_in_desc);
                let mut anc = ancestors.clone();
                anc.insert(0, (c.real_depth, c.node.size));
                emit_rows(c, ind, anc, true, &mut rows);
            } else {
                let mut ind = indent.clone();
                ind.push(!c.last_in_desc);
                let mut anc = ancestors.clone();
                anc.insert(0, (c.real_depth, c.node.size));
                emit_rows(c, ind, anc, false, &mut rows);
            }
        }
    } else if opts.reverse {
        let ancestors: Vec<(usize, u64)> = Vec::new();
        emit_rows(&sorted, Vec::new(), ancestors, true, &mut rows);
    } else {
        let ancestors: Vec<(usize, u64)> = Vec::new();
        emit_rows(&sorted, Vec::new(), ancestors, false, &mut rows);
    }
    let rows = filter_rows(rows, opts);
    let layout = compute_layout(&rows, root.size, opts);
    if layout.size_width + 2 >= opts.terminal_width {
        panic!("Not enough terminal width");
    }
    if opts.screen_reader {
        print_screen_reader(&rows, &layout, opts, colors, root.size);
    } else {
        print_tree(&rows, &layout, opts, colors, root.size);
    }
}

'''
