        let mut c = c;
        filter_dirs(&mut c);
        if c.node.is_folder() || c.node.real_depth_is_root {
            kept.push(c);
        }
    }
    node.children = kept;
    relabel(node);
}

/// Keeps only leaf nodes (-F).
fn filter_files<'a>(node: &mut SNode<'a>) {
    let mut kept: Vec<SNode<'a>> = Vec::new();
    for c in node.children.drain(..) {
        let mut c = c;
        filter_files(&mut c);
        if c.children.is_empty() {
            kept.push(c);
        }
    }
    node.children = kept;
    relabel(node);
}

fn relabel<'a>(node: &mut SNode<'a>) {
    let last = node.children.len().saturating_sub(1);
    for (i, c) in node.children.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
}

