/// Writes the (pruned) tree as JSON: children in descending size order.
fn write_json_node<'a>(node: &SNode<'a>, opts: &DisplayOpts, out: &mut String) {
    let size = size_str(node.node.size, opts);
    let name = node.node.path.to_string_lossy().to_string();
