fn flatten_leaves<'a>(node: &SNode<'a>, out: &mut Vec<SNode<'a>>) {
    if node.children.is_empty() {
        out.push(SNode {
            node: node.node,
            children: Vec::new(),
            real_depth: node.real_depth,
            last_in_desc: true,
            is_biggest: false,
            kept: true,
        });
        return;
    }
    for c in node.children.iter() {
        flatten_leaves(c, out);
    }
}

fn filter_files<'a>(node: &mut SNode<'a>) {
    let mut leaves: Vec<SNode<'a>> = Vec::new();
    for c in node.children.iter() {
        flatten_leaves(c, &mut leaves);
    }
    leaves.sort_by(|a, b| {
        a.node.size
            .cmp(&b.node.size)
            .then_with(|| a.node.name.cmp(&b.node.name))
    });
    let last = leaves.len().saturating_sub(1);
    for (i, c) in leaves.iter_mut().enumerate() {
        c.last_in_desc = i == last;
        c.is_biggest = i == 0;
    }
    node.children = leaves;
}""")
